// runMigrateCheckpointsV2DryRun reports v1 checkpoints that have no matching
// entry on the v2 /main ref. It writes nothing and exits non-zero when any
// checkpoint is pending, so scripts can gate work on migration completeness.
func runMigrateCheckpointsV2DryRun(ctx context.Context, cmd *cobra.Command) error {
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		cmd.SilenceUsage = true
		fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
		return NewSilentError(err)
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
	out := cmd.OutOrStdout()

	v1List, err := v1Store.ListCommitted(ctx)
	if err != nil {
		return fmt.Errorf("failed to list v1 checkpoints: %w", err)
	}
	if len(v1List) == 0 {
		fmt.Fprintln(out, "No v1 checkpoints found.")
		return nil
	}

	v2List, err := v2Store.ListCommitted(ctx)
	if err != nil {
		return fmt.Errorf("failed to list v2 checkpoints: %w", err)
	}
	v2Set := make(map[string]struct{}, len(v2List))
	for _, info := range v2List {
		v2Set[info.CheckpointID.String()] = struct{}{}
	}

	pending := make([]checkpoint.CommittedInfo, 0)
	for _, info := range v1List {
		if _, ok := v2Set[info.CheckpointID.String()]; !ok {
			pending = append(pending, info)
		}
	}

	if len(pending) == 0 {
		fmt.Fprintf(out, "All %d v1 checkpoints are already in v2. Nothing to migrate.\n", len(v1List))
		return nil
	}

	sortMigratableCheckpoints(pending)

	root, _ := paths.WorktreeRoot(ctx)
	fmt.Fprintf(out, "%d of %d v1 checkpoints not yet in v2:\n\n", len(pending), len(v1List))
	for _, info := range pending {
		when := "(unknown time)   "
		if !info.CreatedAt.IsZero() {
			when = info.CreatedAt.Local().Format("2006-01-02 15:04")
		}
		sha := lookupV1CommitForCheckpoint(ctx, root, info.CheckpointID.String())
		fmt.Fprintf(out, "  %s  %s  %s\n", info.CheckpointID, when, sha)
	}
	fmt.Fprintln(out)
	fmt.Fprintln(out, "Run 'entire migrate --checkpoints v2' to migrate these.")

	return NewSilentError(fmt.Errorf("%d v1 checkpoint(s) pending migration to v2", len(pending)))
}

// lookupV1CommitForCheckpoint returns the short hash of the most recent commit
// on entire/checkpoints/v1 whose subject names the given checkpoint ID, or
// "-------" when the lookup fails (branch absent, no match, git error). The
// SHA is purely informational — its absence never blocks the dry-run report.
func lookupV1CommitForCheckpoint(ctx context.Context, repoRoot, checkpointID string) string {
	const placeholder = "-------"
	if repoRoot == "" {
		return placeholder
	}
	gitCmd := exec.CommandContext(ctx, "git", "log", "entire/checkpoints/v1",
		"--grep", "Checkpoint: "+checkpointID, "--pretty=%h", "-n", "1")
	gitCmd.Dir = repoRoot
	output, err := gitCmd.Output()
	if err != nil {
		return placeholder
	}
	sha := strings.TrimSpace(string(output))
	if sha == "" {
		return placeholder
	}
	return sha
}

